1	import * as THREE from "three";
2	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
3	import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
4	import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
5	import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
6	import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
7	import type {
8	  PostProcessorOptions,
9	  BloomOptions,
10	  VignetteOptions,
11	} from "../types/engine.types.js";
12	import additiveBlendVertexShader from "../../shaders/post-processing/additive-blend.vertex.glsl?raw";
13	import additiveBlendFragmentShader from "../../shaders/post-processing/additive-blend.fragment.glsl?raw";
14	import { VignetteShader } from "three/addons/shaders/VignetteShader.js";
15	
16	const DEFAULT_BLOOM: Required<Omit<BloomOptions, "selective">> & {
17	  selective: boolean;
18	} = {
19	  strength: 0.12,
20	  radius: 0.35,
21	  threshold: 0.93,
22	  compositeStrength: 0.4,
23	  selective: true,
24	};
25	
26	const DEFAULT_VIGNETTE: Required<VignetteOptions> = {
27	  offset: 0.95,
28	  darkness: 1.45,
29	};
30	
31	export class PostProcessor {
32	  private _renderer: THREE.WebGLRenderer;
33	  private _scene: THREE.Scene;
34	  private _camera: THREE.Camera;
35	  private _opts: PostProcessorOptions;
36	
37	  private _composer: EffectComposer | null = null;
38	  private _bloomComposer: EffectComposer | null = null;
39	  private _finalComposer: EffectComposer | null = null;
40	  private _bloomPass: UnrealBloomPass | null = null;
41	  private _blendPass: ShaderPass | null = null;
42	  private _vignettePass: ShaderPass | null = null;
43	  private _selective = false;
44	
45	  private _darkMaterial: THREE.MeshBasicMaterial | null = null;
46	  private _materialCache = new Map<
47	    THREE.Object3D,
48	    THREE.Material | THREE.Material[]
49	  >();
50	  private _bloomDescendants = new Set<THREE.Object3D>();
51	  private _cachedBloomSignature = "";
52	  private _cachedNonBloomMeshes: THREE.Mesh[] = [];
53	  private _cachedSceneMeshes: THREE.Mesh[] = [];
54	  private _didWarnSelectiveFallback = false;
55	
56	  constructor(
57	    renderer: THREE.WebGLRenderer,
58	    scene: THREE.Scene,
59	    camera: THREE.Camera,
60	    opts: PostProcessorOptions = {},
61	  ) {
62	    this._renderer = renderer;
63	    this._scene = scene;
64	    this._camera = camera;
65	    this._opts = opts;
66	    this._setup();
67	  }
68	
69	  get isSelective(): boolean {
70	    return this._selective;
71	  }
72	
73	  private _setup(): void {
74	    const bloomOpt = this._opts.bloom;
75	    const vignetteOpt = this._opts.vignette;
76	    const hasBloom = bloomOpt !== false;
77	    const hasVignette = vignetteOpt !== false && vignetteOpt != null;
78	    if (!hasBloom && !hasVignette) {
79	      return;
80	    }
81	    const vignetteCfg = this._normalizeVignetteOptions(vignetteOpt);
82	    if (!hasBloom) {
83	      this._setupCustomPassPipeline(vignetteCfg);
84	      return;
85	    }
86	    const bloomCfg = this._normalizeBloomOptions(bloomOpt);
87	
88	    this._selective = bloomCfg.selective ?? true;
89	    const resolution = new THREE.Vector2(
90	      this._renderer.domElement.width,
91	      this._renderer.domElement.height,
92	    );
93	
94	    if (this._selective) {
95	      this._setupSelectiveBloom(bloomCfg, resolution, vignetteCfg);
96	      return;
97	    }
98	    this._setupGlobalBloom(bloomCfg, resolution, vignetteCfg);
99	  }
100	
101	  private _setupSelectiveBloom(
102	    cfg: Required<Omit<BloomOptions, "selective">> & { selective: boolean },
103	    resolution: THREE.Vector2,
104	    vignetteCfg: Required<VignetteOptions> | null,
105	  ): void {
106	    this._darkMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
107	
108	    this._bloomComposer = new EffectComposer(this._renderer);
109	    this._bloomComposer.renderToScreen = false;
110	    this._bloomComposer.addPass(new RenderPass(this._scene, this._camera));
111	    this._bloomPass = new UnrealBloomPass(
112	      resolution,
113	      cfg.strength,
114	      cfg.radius,
115	      cfg.threshold,
116	    );
117	    this._bloomComposer.addPass(this._bloomPass);
118	
119	    this._finalComposer = new EffectComposer(this._renderer);
120	    this._finalComposer.addPass(new RenderPass(this._scene, this._camera));
121	
122	    const blendPass = new ShaderPass(
123	      new THREE.ShaderMaterial({
124	        uniforms: {
125	          baseTexture: { value: null },
126	          bloomTexture: {
127	            value: this._bloomComposer.renderTarget2.texture,
128	          },
129	          bloomMix: { value: cfg.compositeStrength },
130	        },
131	        vertexShader: additiveBlendVertexShader,
132	        fragmentShader: additiveBlendFragmentShader,
133	        defines: {},
134	      }),
135	      "baseTexture",
136	    );
137	    blendPass.needsSwap = true;
138	    this._blendPass = blendPass;
139	    this._finalComposer.addPass(blendPass);
140	    if (vignetteCfg) {
141	      this._vignettePass = this._createVignettePass(vignetteCfg);
142	      this._finalComposer.addPass(this._vignettePass);
143	    }
144	  }
145	
146	  private _setupGlobalBloom(
147	    bloomCfg: Required<Omit<BloomOptions, "selective">> & {
148	      selective: boolean;
149	    },
150	    resolution: THREE.Vector2,
151	    vignetteCfg: Required<VignetteOptions> | null,
152	  ): void {
153	    this._composer = new EffectComposer(this._renderer);
154	    this._composer.addPass(new RenderPass(this._scene, this._camera));
155	    this._bloomPass = new UnrealBloomPass(
156	      resolution,
157	      bloomCfg.strength,
158	      bloomCfg.radius,
159	      bloomCfg.threshold,
160	    );
161	    this._composer.addPass(this._bloomPass);
162	    if (vignetteCfg) {
163	      this._vignettePass = this._createVignettePass(vignetteCfg);
164	      this._composer.addPass(this._vignettePass);
165	    }
166	  }
167	
168	  private _setupCustomPassPipeline(
169	    vignetteCfg: Required<VignetteOptions> | null,
170	  ): void {
171	    this._composer = new EffectComposer(this._renderer);
172	    this._composer.addPass(new RenderPass(this._scene, this._camera));
173	    if (vignetteCfg) {
174	      this._vignettePass = this._createVignettePass(vignetteCfg);
175	      this._composer.addPass(this._vignettePass);
176	    }
177	  }
178	
179	  render(bloomRoots: Set<THREE.Object3D>, deltaTime?: number): void {
180	    if (!this._bloomPass) {
181	      if (this._composer) {
182	        this._composer.render(deltaTime);
183	        return;
184	      }
185	      this._renderer.render(this._scene, this._camera);
186	      return;
187	    }
188	
189	    if (this._selective) {
190	      const hasRoots = this._hasRenderableBloomRoots(bloomRoots);
191	      this._renderSelective(bloomRoots, hasRoots, deltaTime);
192	      return;
193	    }
194	    this._composer?.render(deltaTime);
195	  }
196	
197	  private _renderSelective(
198	    bloomRoots: Set<THREE.Object3D>,
199	    hasRoots: boolean,
200	    deltaTime?: number,
201	  ): void {
202	    if (
203	      !this._selective ||
204	      !this._bloomComposer ||
205	      !this._finalComposer ||
206	      !this._darkMaterial
207	    ) {
208	      this._composer?.render(deltaTime);
209	      return;
210	    }
211	    if (!hasRoots) {
212	      this._renderer.render(this._scene, this._camera);
213	      return;
214	    }
215	
216	    try {
217	      try {
218	        this._prepareBloomScene(hasRoots, bloomRoots);
219	        this._bloomComposer.render(deltaTime);
220	      } finally {
221	        this._restoreMaterials();
222	      }
223	      this._finalComposer.render(deltaTime);
224	    } catch (error) {
225	      if (!this._didWarnSelectiveFallback) {
226	        this._didWarnSelectiveFallback = true;
227	      }
228	      this._renderer.render(this._scene, this._camera);
229	    }
230	  }
231	
232	  private _prepareBloomScene(
233	    hasRoots: boolean,
234	    bloomRoots: Set<THREE.Object3D>,
235	  ): void {
236	    if (hasRoots) {
237	      this._darkenNonBloom(bloomRoots);
238	      return;
239	    }
240	    this._darkenAllMeshes();
241	  }
242	
243	  private _darkenNonBloom(bloomRoots: Set<THREE.Object3D>): void {
244	    const dark = this._darkMaterial!;
245	    this._materialCache.clear();
246	    const signature = this._createBloomSignature(bloomRoots);
247	    if (signature !== this._cachedBloomSignature) {
248	      this._cachedBloomSignature = signature;
249	      this._rebuildNonBloomMeshCache(bloomRoots);
250	    }
251	
252	    for (const mesh of this._cachedNonBloomMeshes) {
253	      this._materialCache.set(mesh, mesh.material);
254	      mesh.material = dark;
255	    }
256	  }
257	
258	  private _darkenAllMeshes(): void {
259	    const dark = this._darkMaterial!;
260	    this._materialCache.clear();
261	    if (this._cachedSceneMeshes.length === 0) {
262	      this._cachedSceneMeshes = this._collectSceneMeshes();
263	    }
264	    for (const mesh of this._cachedSceneMeshes) {
265	      this._materialCache.set(mesh, mesh.material);
266	      mesh.material = dark;
267	    }
268	  }
269	
270	  private _hasRenderableBloomRoots(bloomRoots: Set<THREE.Object3D>): boolean {
271	    if (bloomRoots.size === 0) return false;
272	    for (const root of bloomRoots) {
273	      if (root.parent) return true;
274	    }
275	    return false;
276	  }
277	
278	  private _normalizeBloomOptions(
279	    bloomOpt: PostProcessorOptions["bloom"],
280	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
281	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
282	      return { ...DEFAULT_BLOOM };
283	    }
284	    const strength = this._clampFinite(
285	      bloomOpt.strength,
286	      DEFAULT_BLOOM.strength,
287	      0,
288	      5,
289	    );
290	    const radius = this._clampFinite(
291	      bloomOpt.radius,
292	      DEFAULT_BLOOM.radius,
293	      0,
294	      2,
295	    );
296	    const threshold = this._clampFinite(
297	      bloomOpt.threshold,
298	      DEFAULT_BLOOM.threshold,
299	      0,
300	      2,
301	    );
302	    const compositeStrength = this._clampFinite(
303	      bloomOpt.compositeStrength,
304	      DEFAULT_BLOOM.compositeStrength,
305	      0,
306	      1,
307	    );
308	    const selective =
309	      typeof bloomOpt.selective === "boolean"
310	        ? bloomOpt.selective
311	        : DEFAULT_BLOOM.selective;
312	    return { strength, radius, threshold, compositeStrength, selective };
313	  }
314	
315	  private _normalizeVignetteOptions(
316	    vignetteOpt: PostProcessorOptions["vignette"],
317	  ): Required<VignetteOptions> | null {
318	    if (vignetteOpt === false || vignetteOpt == null) return null;
319	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
320	    return {
321	      offset: this._clampFinite(
322	        vignetteOpt.offset,
323	        DEFAULT_VIGNETTE.offset,
324	        0,
325	        4,
326	      ),
327	      darkness: this._clampFinite(
328	        vignetteOpt.darkness,
329	        DEFAULT_VIGNETTE.darkness,
330	        0,
331	        4,
332	      ),
333	    };
334	  }
335	
336	  private _createVignettePass(
337	    vignetteCfg: Required<VignetteOptions>,
338	  ): ShaderPass {
339	    const pass = new ShaderPass(VignetteShader);
340	    pass.uniforms.offset.value = vignetteCfg.offset;
341	    pass.uniforms.darkness.value = vignetteCfg.darkness;
342	    return pass;
343	  }
344	
345	  private _clampFinite(
346	    value: number | undefined,
347	    fallback: number,
348	    min: number,
349	    max: number,
350	  ): number {
351	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
352	    return Math.max(min, Math.min(max, value));
353	  }
354	
355	  private _restoreMaterials(): void {
356	    for (const [mesh, material] of this._materialCache) {
357	      (mesh as THREE.Mesh).material = material;
358	    }
359	    this._materialCache.clear();
360	  }
361	
362	  private _createBloomSignature(bloomRoots: Set<THREE.Object3D>): string {
363	    return Array.from(bloomRoots)
364	      .filter((root) => !!root.parent)
365	      .map((root) => root.uuid)
366	      .sort()
367	      .join("|");
368	  }
369	
370	  private _rebuildNonBloomMeshCache(bloomRoots: Set<THREE.Object3D>): void {
371	    this._bloomDescendants.clear();
372	    for (const root of bloomRoots) {
373	      root.traverse((child) => this._bloomDescendants.add(child));
374	    }
375	    this._cachedSceneMeshes = this._collectSceneMeshes();
376	    this._cachedNonBloomMeshes = this._cachedSceneMeshes.filter(
377	      (mesh) => !this._bloomDescendants.has(mesh),
378	    );
379	  }
380	
381	  private _collectSceneMeshes(): THREE.Mesh[] {
382	    const meshes: THREE.Mesh[] = [];
383	    this._scene.traverse((obj) => {
384	      const mesh = obj as THREE.Mesh;
385	      if (!mesh.isMesh) return;
386	      meshes.push(mesh);
387	    });
388	    return meshes;
389	  }
390	
391	  resize(width: number, height: number, pixelRatio?: number): void {
392	    const dpr =
393	      pixelRatio ??
394	      Math.min(
395	        ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
396	        2,
397	      );
398	
399	    if (this._selective) {
400	      this._bloomComposer?.setSize(width, height);
401	      this._bloomComposer?.setPixelRatio(dpr);
402	      this._finalComposer?.setSize(width, height);
403	      this._finalComposer?.setPixelRatio(dpr);
404	    } else {
405	      this._composer?.setSize(width, height);
406	      this._composer?.setPixelRatio(dpr);
407	    }
408	
409	    if (this._bloomPass) {
410	      this._bloomPass.resolution.set(width, height);
411	    }
412	  }
413	
414	  getComposer(): EffectComposer | null {
415	    return this._selective ? this._finalComposer : this._composer;
416	  }
417	
418	  getBloomPass(): UnrealBloomPass | null {
419	    return this._bloomPass;
420	  }
421	
422	  getBloomOptions(): Required<Omit<BloomOptions, "selective">> | null {
423	    if (!this._bloomPass) return null;
424	    return {
425	      strength: this._bloomPass.strength,
426	      radius: this._bloomPass.radius,
427	      threshold: this._bloomPass.threshold,
428	      compositeStrength: this._readBloomCompositeStrength(),
429	    };
430	  }
431	
432	  setBloomOptions(options: BloomOptions): void {
433	    if (!this._bloomPass) return;
434	    const normalized = this._normalizeBloomOptions(options);
435	    this._bloomPass.strength = normalized.strength;
436	    this._bloomPass.radius = normalized.radius;
437	    this._bloomPass.threshold = normalized.threshold;
438	    const blendUniform = this._blendPass?.uniforms?.bloomMix;
439	    if (blendUniform) {
440	      blendUniform.value = normalized.compositeStrength;
441	    }
442	  }
443	
444	  getVignetteOptions(): Required<VignetteOptions> | null {
445	    const uniforms = this._vignettePass?.uniforms;
446	    if (!uniforms) return null;
447	    return {
448	      offset: uniforms.offset.value,
449	      darkness: uniforms.darkness.value,
450	    };
451	  }
452	
453	  setVignetteOptions(options: VignetteOptions): void {
454	    const uniforms = this._vignettePass?.uniforms;
455	    if (!uniforms) return;
456	    const normalized = this._normalizeVignetteOptions(options);
457	    if (!normalized) return;
458	    uniforms.offset.value = normalized.offset;
459	    uniforms.darkness.value = normalized.darkness;
460	  }
461	
462	  dispose(): void {
463	    this._composer?.dispose();
464	    this._composer = null;
465	    this._bloomComposer?.dispose();
466	    this._bloomComposer = null;
467	    this._finalComposer?.dispose();
468	    this._finalComposer = null;
469	    this._bloomPass?.dispose();
470	    this._bloomPass = null;
471	    this._blendPass = null;
472	    this._vignettePass = null;
473	    this._darkMaterial?.dispose();
474	    this._darkMaterial = null;
475	    this._materialCache.clear();
476	    this._bloomDescendants.clear();
477	    this._cachedBloomSignature = "";
478	    this._cachedNonBloomMeshes = [];
479	    this._cachedSceneMeshes = [];
480	    this._didWarnSelectiveFallback = false;
481	  }
482	
483	  private _readBloomCompositeStrength(): number {
484	    const uniform = this._blendPass?.uniforms?.bloomMix;
485	    if (!uniform || typeof uniform.value !== "number") {
486	      return DEFAULT_BLOOM.compositeStrength;
487	    }
488	    return uniform.value;
489	  }
490	}
