1	import * as THREE from "three";
2	import type {
3	  SceneObjectContext,
4	  TweenApplyMode,
5	} from "../types/engine.types.js";
6	import type { ISceneObject } from "../types/engine.types.js";
7	import type { ObjectEffects } from "../types/object.types.js";
8	import type {
9	  ShaderManagerRuntimePort,
10	  ShaderRegistration,
11	} from "../types/shader.types.js";
12	import { Helpers } from "../utils/Helpers.js";
13	
14	export abstract class SceneObject<
15	  TTweenProps = Record<string, unknown>,
16	> implements ISceneObject {
17	  protected _context: SceneObjectContext | null = null;
18	  protected _disposed = false;
19	  private readonly _shaderOwnerId = `shader-owner-${Math.random().toString(36).slice(2, 10)}`;
20	  private _timelineRoot: THREE.Group | null = null;
21	  private _effects: ObjectEffects = {};
22	  private _visible = true;
23	  private _ownedTextures = new Set<THREE.Texture>();
24	
25	  init(context?: SceneObjectContext): void | Promise<void> {
26	    if (context) {
27	      this._context = context;
28	      return;
29	    }
30	    return this.runObject();
31	  }
32	
33	  abstract runObject(): void | Promise<void>;
34	
35	  abstract runUpdate(_deltaTime: number): void;
36	
37	  getAnimationTarget(): THREE.Object3D | Record<string, unknown> | null {
38	    return this._timelineRoot;
39	  }
40	
41	  getBloomTarget(): THREE.Object3D | null {
42	    const target = this.getAnimationTarget();
43	    if (target instanceof THREE.Object3D) return target;
44	    return this._timelineRoot;
45	  }
46	
47	  getTweenApplyMode(): TweenApplyMode {
48	    return "gsapOnly";
49	  }
50	
51	  setEffects(effects: ObjectEffects): void {
52	    this._effects = { ...effects };
53	  }
54	
55	  getEffects(): ObjectEffects {
56	    return this._effects;
57	  }
58	
59	  getBloomEnabled(): boolean {
60	    return this._effects.bloom?.enabled ?? false;
61	  }
62	
63	  protected ensureTimelineRoot(name?: string): THREE.Group | null {
64	    if (this._timelineRoot) return this._timelineRoot;
65	    const scene = this._context?.scene;
66	    if (!scene) return null;
67	    const root = new THREE.Group();
68	    if (name) root.name = name;
69	    scene.add(root);
70	    this._timelineRoot = root;
71	    this._applyOptionVisibility();
72	    return root;
73	  }
74	
75	  protected attachToTimelineRoot(obj: THREE.Object3D, rootName?: string): void {
76	    const root = this.ensureTimelineRoot(rootName);
77	    if (!root) return;
78	    if (obj.parent && obj.parent !== root) obj.parent.remove(obj);
79	    root.add(obj);
80	  }
81	
82	  protected resolveAssetPath(assetUrl: string): string {
83	    const base =
84	      typeof document !== "undefined"
85	        ? (document.documentElement?.getAttribute?.("data-base") ?? "")
86	        : "";
87	    return `${base}${assetUrl}`.replace(/\/+/g, "/");
88	  }
89	
90	  protected getTimelineRoot(): THREE.Group | null {
91	    return this._timelineRoot;
92	  }
93	
94	  protected getShaderManager(): ShaderManagerRuntimePort | null {
95	    const candidate = this._context?.getObject("env.shaderManager.runtime");
96	    if (!candidate || typeof candidate !== "object") return null;
97	    const manager = candidate as unknown as ShaderManagerRuntimePort;
98	    if (typeof manager.register !== "function") return null;
99	    return manager;
100	  }
101	
102	  protected registerShader(registration: ShaderRegistration): void {
103	    this.getShaderManager()?.register(registration);
104	  }
105	
106	  protected getShaderOwnerId(): string {
107	    return this._shaderOwnerId;
108	  }
109	
110	  protected createShaderKey(suffix: string): string {
111	    return `${this._shaderOwnerId}.${suffix}`;
112	  }
113	
114	  protected releaseShaders(ownerId: string): void {
115	    this.getShaderManager()?.release(ownerId);
116	  }
117	
118	  protected offTimelineRoot(): void {
119	    if (this._timelineRoot?.parent) {
120	      this._timelineRoot.parent.remove(this._timelineRoot);
121	    }
122	    this._timelineRoot = null;
123	  }
124	
125	  setTimelineVars(vars: Partial<TTweenProps>, _kind: "from" | "to"): void {
126	    if (vars == null || Object.keys(vars as object).length === 0) return;
127	    const normalized = this.normalizeTimelineVars(
128	      vars as Record<string, unknown>,
129	    );
130	    this.mergeOptionsFromTimeline(normalized as Partial<TTweenProps>);
131	    this._applyOptionVisibility();
132	    this.syncFromOptions();
133	  }
134	
135	  protected normalizeTimelineVars(
136	    vars: Record<string, unknown>,
137	  ): Record<string, unknown> {
138	    return Helpers.normalizeControlVars(vars);
139	  }
140	
141	  protected getOptions(): Record<string, unknown> {
142	    return {};
143	  }
144	
145	  getRuntimeOptions(): Record<string, unknown> {
146	    return this.getOptions();
147	  }
148	
149	  protected mergeOptionsFromTimeline(vars: Partial<TTweenProps>): void {
150	    const options = this.getOptions();
151	    if (options && typeof options === "object" && Object.keys(vars as object).length > 0) {
152	      Object.assign(options, vars);
153	    }
154	  }
155	
156	  protected syncFromOptions(): void {}
157	  protected abstract applyVisibility(visible: boolean): void;
158	  protected isAlwaysVisible(): boolean {
159	    return false;
160	  }
161	
162	  setVisibleOn(): void {
163	    this._setVisibility(true);
164	  }
